), updated AS (
    UPDATE pets.ingredients AS ingredient
    SET category = source.category,
        name = source.name,
        subtype = source.subtype,
        recommender_supported = TRUE,
        calories = source.calories,
        protein = source.protein,
        fat = source.fat,
        carbs = source.carbs,
        moisture = source.moisture,
        fiber = source.fiber,
        ash = source.ash,
        cholesterol = source.cholesterol,
        sugar = source.sugar,
        calcium = source.calcium,
        phosphorus = source.phosphorus,
        magnesium = source.magnesium,
        sodium = source.sodium,
        potassium = source.potassium,
        iron = source.iron,
        copper = source.copper,
        zinc = source.zinc,
        manganese = source.manganese,
        linoleic = source.linoleic,
        alpha_linolenic = source.alpha_linolenic,
        arachidonic = source.arachidonic,
        epa = source.epa,
        dha = source.dha,
        choline = source.choline,
        selenium = source.selenium,
        iodine = source.iodine,
        vitamin_a = source.vitamin_a,
        vitamin_e = source.vitamin_e,
        vitamin_d = source.vitamin_d,
        vitamin_b1 = source.vitamin_b1,
        vitamin_b2 = source.vitamin_b2,
        vitamin_b3 = source.vitamin_b3,
        vitamin_b5 = source.vitamin_b5,
        vitamin_b6 = source.vitamin_b6,
        vitamin_b9 = source.vitamin_b9,
        vitamin_b12 = source.vitamin_b12,
        vitamin_c = source.vitamin_c,
        vitamin_k = source.vitamin_k,
        alpha_carotene = source.alpha_carotene,
        beta_carotene = source.beta_carotene,
        beta_cryptoxanthin = source.beta_cryptoxanthin,
        lutein_zeaxanthin = source.lutein_zeaxanthin,
        lycopene = source.lycopene,
        retinol = source.retinol,
        updated_at = NOW()
    FROM source
    WHERE ingredient.owner_id IS NULL
      AND lower(ingredient.name) = lower(source.match_name)
      AND lower(coalesce(ingredient.subtype, '')) = lower(source.match_subtype)
    RETURNING source.source_row
)
INSERT INTO pets.ingredients (category, name, subtype, recommender_supported, owner_id, portion, calories, protein, fat, carbs, moisture, fiber, ash, cholesterol, sugar, calcium, phosphorus, magnesium, sodium, potassium, iron, copper, zinc, manganese, linoleic, alpha_linolenic, arachidonic, epa, dha, choline, selenium, iodine, vitamin_a, vitamin_e, vitamin_d, vitamin_b1, vitamin_b2, vitamin_b3, vitamin_b5, vitamin_b6, vitamin_b9, vitamin_b12, vitamin_c, vitamin_k, alpha_carotene, beta_carotene, beta_cryptoxanthin, lutein_zeaxanthin, lycopene, retinol, created_at, updated_at)
SELECT source.category, source.name, source.subtype, TRUE, NULL, 100, source.calories, source.protein, source.fat, source.carbs, source.moisture, source.fiber, source.ash, source.cholesterol, source.sugar, source.calcium, source.phosphorus, source.magnesium, source.sodium, source.potassium, source.iron, source.copper, source.zinc, source.manganese, source.linoleic, source.alpha_linolenic, source.arachidonic, source.epa, source.dha, source.choline, source.selenium, source.iodine, source.vitamin_a, source.vitamin_e, source.vitamin_d, source.vitamin_b1, source.vitamin_b2, source.vitamin_b3, source.vitamin_b5, source.vitamin_b6, source.vitamin_b9, source.vitamin_b12, source.vitamin_c, source.vitamin_k, source.alpha_carotene, source.beta_carotene, source.beta_cryptoxanthin, source.lutein_zeaxanthin, source.lycopene, source.retinol, NOW(), NOW()
FROM source
WHERE NOT EXISTS (SELECT 1 FROM updated WHERE updated.source_row = source.source_row)
  AND NOT EXISTS (
      SELECT 1 FROM pets.ingredients AS ingredient
      WHERE ingredient.owner_id IS NULL
        AND lower(ingredient.name) = lower(source.name)
        AND lower(coalesce(ingredient.subtype, '')) = lower(source.subtype)
  );
